files.cts/core/v1/suites/01-baseline.json:
{
  "meta": {
    "suite_id": "baseline",
    "lane": "core",
    "sut_protocol": "cts.protocol.v1",
    "spec_refs": [
      "specs/04-official/v1/AEON-spec-v1.md"
    ]
  },
  "id": "baseline",
  "title": "Core Baseline Parse and Addressing",
  "tests": [
    {
      "id": "core-baseline-001",
      "description": "Simple strict parse succeeds with normalized binding projection",
      "input": {
        "source": "a:number = 1",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.a",
              "datatype": "number",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "parse-pass"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-type-system",
        "specs/04-official/v1/AEON-spec-v1.md#11-processing-phases"
      ]
    },
    {
      "id": "core-baseline-002",
      "description": "Invalid syntax fails with deterministic parse diagnostic shape",
      "input": {
        "source": "a = {",
        "mode": "transport"
      },
      "expected": {
        "ok": false,
        "errors": [
          {
            "code": "SYNTAX_ERROR",
            "path": "$",
            "phase": null
          }
        ],
        "warnings": [],
        "result": {
          "parse_ok": false
        }
      },
      "tags": [
        "baseline",
        "parse-fail"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#11-processing-phases"
      ]
    },
    {
      "id": "core-baseline-003-strict-reserved-only-custom-datatype-reject",
      "description": "Strict mode rejects custom datatype by default (reserved_only)",
      "input": {
        "source": "aeon:mode = \"strict\"\ncolor:stroke = #ff00ff",
        "mode": "strict"
      },
      "expected": {
        "ok": false,
        "errors": [
          {
            "code": "CUSTOM_DATATYPE_NOT_ALLOWED",
            "path": "$.color",
            "phase": null
          }
        ],
        "warnings": [],
        "result": {
          "parse_ok": false
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "strict"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport",
        "specs/04-official/v1/AEON-v1-compliance.md#7-strict-mode-requirements"
      ]
    },
    {
      "id": "core-baseline-004-strict-allow-custom-datatype-pass",
      "description": "Strict mode accepts custom datatype when datatype policy is allow_custom",
      "input": {
        "source": "aeon:mode = \"strict\"\ncolor:stroke = #ff00ff",
        "mode": "strict",
        "options": {
          "datatype_policy": "allow_custom"
        }
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.color",
              "datatype": "stroke",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "strict"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport",
        "specs/04-official/v1/AEON-v1-compliance.md#7-strict-mode-requirements"
      ]
    },
    {
      "id": "core-baseline-005-strict-rich-preset-allows-custom-datatype",
      "description": "Strict mode accepts custom datatype when rich preset is enabled",
      "input": {
        "source": "aeon:mode = \"strict\"\ncolor:stroke = #ff00ff",
        "mode": "strict",
        "options": {
          "rich": true
        }
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.color",
              "datatype": "stroke",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "strict",
        "rich-preset"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport",
        "specs/04-official/v1/AEON-v1-compliance.md#7-strict-mode-requirements"
      ]
    },
    {
      "id": "core-baseline-006-strict-reserved-datatype-literal-mismatch",
      "description": "Strict mode rejects reserved datatype/literal mismatches",
      "input": {
        "source": "aeon:mode = \"strict\"\nstroke:number = #ff00ff",
        "mode": "strict"
      },
      "expected": {
        "ok": false,
        "errors": [
          {
            "code": "DATATYPE_LITERAL_MISMATCH",
            "path": "$.stroke",
            "phase": null
          }
        ],
        "warnings": [],
        "result": {
          "parse_ok": false
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "strict",
        "reserved-datatype"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport",
        "specs/04-official/v1/AEON-v1-compliance.md#7-strict-mode-requirements"
      ]
    },
    {
      "id": "core-baseline-007-transport-explicit-reserved-datatype-literal-mismatch",
      "description": "Transport mode still rejects explicit reserved datatype/literal mismatches",
      "input": {
        "source": "aeon:mode = \"transport\"\nstate:toggle = true",
        "mode": "transport"
      },
      "expected": {
        "ok": false,
        "errors": [
          {
            "code": "DATATYPE_LITERAL_MISMATCH",
            "path": "$.state",
            "phase": null
          }
        ],
        "warnings": [],
        "result": {
          "parse_ok": false
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "transport",
        "reserved-datatype"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#8-strictness-and-datatype-policy",
        "specs/04-official/v1/AEON-v1-compliance.md#7-strict-mode-requirements"
      ]
    },
    {
      "id": "core-baseline-008-transport-explicit-reserved-datatype-match",
      "description": "Transport mode allows explicit reserved datatype when literal matches",
      "input": {
        "source": "aeon:mode = \"transport\"\nstate:toggle = on",
        "mode": "transport"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.state",
              "datatype": "toggle",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "transport",
        "reserved-datatype"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#8-strictness-and-datatype-policy"
      ]
    },
    {
      "id": "core-baseline-008b-strict-header-metadata-untyped-pass",
      "description": "Strict mode treats structured header metadata as control-plane data rather than payload bindings",
      "input": {
        "source": "aeon:header = {\n  mode = \"strict\"\n  meta = {\n    document:string = \"public\"\n  }\n}",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.[\"aeon:meta\"].document",
              "datatype": "string",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "strict",
        "header",
        "control-plane"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport",
        "specs/04-official/v1/AEON-v1-compliance.md#7-strict-mode-requirements"
      ]
    },
    {
      "id": "core-baseline-008c-strict-header-payload-typed-pass",
      "description": "Strict mode accepts typed structured header payload bindings",
      "input": {
        "source": "aeon:header = {\n  mode = \"strict\"\n  meta:object = {\n    document:string = \"public\"\n  }\n}",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.[\"aeon:meta\"].document",
              "datatype": "string",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "strict",
        "header",
        "typing"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport",
        "specs/04-official/v1/AEON-v1-compliance.md#7-strict-mode-requirements"
      ]
    },
    {
      "id": "core-baseline-008d-declared-strict-effective-transport-pass",
      "description": "Consumer-selected transport mode has authority over a document-declared strict mode",
      "input": {
        "source": "aeon:mode = \"strict\"\nname = \"AEON\"",
        "mode": "transport",
        "options": {
          "effective_mode": "transport"
        }
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.name",
              "datatype": null,
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "mode-policy",
        "transport"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport"
      ]
    },
    {
      "id": "core-baseline-008e-declared-transport-effective-strict-reject",
      "description": "Consumer-selected strict mode has authority over a document-declared transport mode",
      "input": {
        "source": "aeon:mode = \"transport\"\nname = \"AEON\"",
        "mode": "strict",
        "options": {
          "effective_mode": "strict"
        }
      },
      "expected": {
        "ok": false,
        "errors": [
          {
            "code": "UNTYPED_VALUE_IN_STRICT_MODE",
            "path": "$.name",
            "phase": null
          }
        ],
        "warnings": [],
        "result": {
          "parse_ok": false
        }
      },
      "tags": [
        "baseline",
        "mode-policy",
        "strict"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-strict-vs-transport"
      ]
    },
    {
      "id": "core-baseline-008f-late-structured-header-reject",
      "description": "Structured headers are rejected when they appear after body bindings",
      "input": {
        "source": "app:object = {\n  name:string = \"playground\"\n}\naeon:header = {\n  mode:string = \"strict\"\n}",
        "mode": "strict"
      },
      "expected": {
        "ok": false,
        "errors": [
          {
            "code": "SYNTAX_ERROR",
            "path": "$",
            "phase": null
          }
        ],
        "warnings": [],
        "result": {
          "parse_ok": false
        }
      },
      "tags": [
        "baseline",
        "header",
        "ordering",
        "reject"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#10-phase-boundaries",
        "specs/04-official/v1/appendices/appendix-canonical-form.md"
      ]
    },
    {
      "id": "core-baseline-008g-tokenized-structured-header-pass",
      "description": "Structured header recognition allows trivia around the aeon:header separators",
      "input": {
        "source": "aeon\n:\nheader /# gap #/= {\n  mode:\nstring = \"strict\"\n  encoding:string = \"utf-8\"\n}\napp:string = \"ok\"",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.app",
              "datatype": "string",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "header",
        "trivia"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#10-phase-boundaries",
        "specs/04-official/v1/appendices/appendix-canonical-form.md"
      ]
    },
    {
      "id": "core-baseline-009-strict-envelope-alias-pass",
      "description": "Strict mode accepts envelope as a reserved object alias",
      "input": {
        "source": "aeon:mode = \"strict\"\nclose:envelope = { hash:string = \"abc\" }",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.close",
              "datatype": "envelope",
              "kind": "binding"
            },
            {
              "path": "$.close.hash",
              "datatype": "string",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "strict",
        "reserved-datatype",
        "envelope"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-type-system",
        "specs/04-official/v1/value-types-v1.md"
      ]
    },
    {
      "id": "core-baseline-009-prose-alias-pass",
      "description": "Strict mode accepts prose as a reserved trimtick alias",
      "input": {
        "source": "aeon:mode = \"strict\"\nbody:prose = >`\n  # Title\n\n  Markdown-ish content.\n`",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.body",
              "datatype": "prose",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "strict",
        "reserved-datatype",
        "prose"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-type-system",
        "specs/04-official/v1/value-types-v1.md"
      ]
    },
    {
      "id": "core-baseline-010-strict-time-literal-pass",
      "description": "Strict mode accepts typed time literals",
      "input": {
        "source": "aeon:mode = \"strict\"\nopens:time = 09:30:00Z",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            {
              "path": "$.opens",
              "datatype": "time",
              "kind": "binding"
            }
          ]
        }
      },
      "tags": [
        "baseline",
        "datatype-policy",
        "strict",
        "reserved-datatype",
        "time"
      ],
      "spec_refs": [
        "specs/04-official/v1/AEON-spec-v1.md#6-type-system",
        "specs/04-official/v1/value-types-v1.md"
      ]
    },
    {
      "id": "core-baseline-010b-strict-radix12-alias-pass",
      "description": "Strict mode accepts radix12 as a reserved radix alias",
      "input": {
