      "expected": {
        "ok": false,
        "errors": [
          { "code": "INVALID_DATE", "phaseLabel": "Parsing" },
          { "code": "INVALID_DATE", "phaseLabel": "Parsing" },
          { "code": "INVALID_DATE", "phaseLabel": "Parsing" },
          { "code": "INVALID_DATE", "phaseLabel": "Parsing" }
        ],
        "warnings": []
      },
      "tags": ["strict", "temporal", "date", "reduced-granularity", "rejection"]
    },
    {
      "id": "core-temporal-009-reduced-date-datetime-accepted",
      "description": "Datetime and WTC values preserve year- and month-granularity date components",
      "input": {
        "source": "year:datetime = 2024-T10:10:00\nmonth:datetime = 2024-12T10:10:00Z\nyearZone:wtc = 2024-T10:10:00&Europe\nmonthZone:wtc = 2024-12T10:&Europe\n",
        "mode": "strict"
      },
      "expected": {
        "ok": true,
        "errors": [],
        "warnings": [],
        "result": {
          "parse_ok": true,
          "bindings": [
            { "path": "$.year", "datatype": "datetime", "kind": "binding" },
            { "path": "$.month", "datatype": "datetime", "kind": "binding" },
            { "path": "$.yearZone", "datatype": "wtc", "kind": "binding" },
            { "path": "$.monthZone", "datatype": "wtc", "kind": "binding" }
          ]
