      "input": {
        "source": "zero:datetime = 0000-T10:10\nmonthZero:datetime = 2024-00T10:10\nmonthHigh:datetime = 2024-13T10:10\nshortMonth:datetime = 2024-2T10:10\n",
        "mode": "strict"
      },
      "expected": {
        "ok": false,
        "errors": [
          { "code": "INVALID_DATETIME", "phaseLabel": "Parsing" },
          { "code": "INVALID_DATETIME", "phaseLabel": "Parsing" },
          { "code": "INVALID_DATETIME", "phaseLabel": "Parsing" },
          { "code": "INVALID_DATETIME", "phaseLabel": "Parsing" }
